package com.renthouse.operation;import com.renthouse.auth.*;import com.renthouse.common.api.*;import com.renthouse.common.exception.BusinessException;import jakarta.validation.*;import jakarta.validation.constraints.*;import java.time.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/landlord/tenants")public class BlacklistController{private final com.renthouse.operation.service.BlacklistService s;public BlacklistController(com.renthouse.operation.service.BlacklistService s){this.s=s;}@PostMapping("/{tenantId}/blacklist")public ApiResponse<Void>block(@PathVariable long tenantId,@RequestBody @Valid Request r){s.block(tenantId,r);return ApiResponse.ok();}@DeleteMapping("/{tenantId}/blacklist")public ApiResponse<Void>unblock(@PathVariable long tenantId){s.unblock(tenantId);return ApiResponse.ok();}public record Request(@NotBlank@Size(max=255)String reason){}}
